import{_ as t}from"./plugin-vue_export-helper-c27b6911.js";import{o as e,c as a,d as n}from"./app-c4483e21.js";const l={},s=n(`<h1 id="edit-game-configuration" tabindex="-1"><a class="header-anchor" href="#edit-game-configuration" aria-hidden="true">#</a> Edit Game Configuration</h1><p>Under the <code>game</code> folder, there is a file named <code>config.txt</code>, you can fill in the relevant information of your game in this file (you can edit it directly using a graphical editor).</p><table><thead><tr><th style="text-align:left;">Parameter</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;">Game_name</td><td style="text-align:left;">Game name</td></tr><tr><td style="text-align:left;">Game_key</td><td style="text-align:left;">Game identification code, 6-10 characters in length, do not repeat with other games</td></tr><tr><td style="text-align:left;">Title_img</td><td style="text-align:left;">Title picture, put it in the <code>background</code> folder</td></tr><tr><td style="text-align:left;">Title_bgm</td><td style="text-align:left;">Title background music, put it in the <code>bgm</code> folder</td></tr><tr><td style="text-align:left;">Game_Logo</td><td style="text-align:left;">Game Logo, multiple can be displayed, separated by |</td></tr><tr><td style="text-align:left;">Enable_Appreciation</td><td style="text-align:left;">Whether to enable the Appreciation feature, including CG and background music appreciation.</td></tr><tr><td style="text-align:left;">Default_Language</td><td style="text-align:left;">Default language, can be set to &#39;zh_CN&#39;, &#39;zh_TW&#39;, &#39;en&#39;, &#39;ja&#39;, &#39;fr&#39;, &#39;de&#39;</td></tr><tr><td style="text-align:left;">Show_panic</td><td style="text-align:left;">Whether to enable the panic button feature, set to true or false</td></tr><tr><td style="text-align:left;">Legacy_Expression_Blend_Mode</td><td style="text-align:left;">Whether to enable legacy expression blend mode for Live2D, set to true or false</td></tr><tr><td style="text-align:left;">Max_line</td><td style="text-align:left;">Maximum number of displayed lines in the text box</td></tr><tr><td style="text-align:left;">Line_height</td><td style="text-align:left;">Line height of the text box (unit: em)</td></tr><tr><td style="text-align:left;">Steam_AppID</td><td style="text-align:left;">Steam App ID, used to initialize Steam integration. Only effective in Electron builds</td></tr></tbody></table><p>The following is a sample configuration file:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#F8F8F2;">Game_name:WebGAL;</span></span>
<span class="line"><span style="color:#F8F8F2;">Game_key:0f33fdGr;</span></span>
<span class="line"><span style="color:#F8F8F2;">Title_img:Title.png;</span></span>
<span class="line"><span style="color:#F8F8F2;">Title_bgm:夏影.mp3;</span></span>
<span class="line"><span style="color:#F8F8F2;">Game_Logo:WebGalEnter.png|bg.png;</span></span>
<span class="line"><span style="color:#F8F8F2;">Enable_Appreciation:true;</span></span>
<span class="line"><span style="color:#F8F8F2;"></span></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="switching-languages" tabindex="-1"><a class="header-anchor" href="#switching-languages" aria-hidden="true">#</a> Switching Languages</h2><p><code>Default_Language</code> only sets the default interface language when the player launches the game for the first time. Players can still switch languages later in <code>Menu -&gt; Options -&gt; System -&gt; Language</code>, and the selected language will be saved locally and reused on the next launch.</p><p>If you also prepare multiple script languages, read the current interface language in your script and jump to the corresponding scene file. You can use the internal variable <code>$userData.optionData.language</code>:</p><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#8BE9FD;">setVar</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">lang=($userData.optionData.language)</span><span style="color:#6272A4;">;</span></span>
<span class="line"><span style="color:#8BE9FD;">changeScene</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">start_zh.txt </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">when</span><span style="color:#FF5555;">=</span><span style="color:#50FA7B;">lang==0</span><span style="color:#6272A4;">;</span></span>
<span class="line"><span style="color:#8BE9FD;">changeScene</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">start_en.txt </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">when</span><span style="color:#FF5555;">=</span><span style="color:#50FA7B;">lang==1</span><span style="color:#6272A4;">;</span></span>
<span class="line"><span style="color:#8BE9FD;">changeScene</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">start_ja.txt </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">when</span><span style="color:#FF5555;">=</span><span style="color:#50FA7B;">lang==2</span><span style="color:#6272A4;">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The numeric values map to languages as follows:</p><table><thead><tr><th style="text-align:left;">Value</th><th style="text-align:left;">Language</th></tr></thead><tbody><tr><td style="text-align:left;">0</td><td style="text-align:left;">Simplified Chinese</td></tr><tr><td style="text-align:left;">1</td><td style="text-align:left;">English</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">Japanese</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">French</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">German</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;">Traditional Chinese</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>Changing the language from the menu only changes the engine UI language. If you want the game script itself to switch too, branch to different scene files in your script as shown above.</p></div>`,12),i=[s];function o(r,d){return e(),a("div",null,i)}const g=t(l,[["render",o],["__file","config.html.vue"]]);export{g as default};
